package org.sleepwell.app;

import android.content.*;import android.content.pm.*;import android.os.*;import android.widget.*;import android.view.*;
import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;
import org.junit.*;import org.junit.runner.RunWith;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
import static org.junit.Assert.*;

/** Fake widget host, private SQLite/preferences and inert RemoteViews. Never binds/pins a launcher. */
@RunWith(AndroidJUnit4.class)
public class HomeWidgetNativeTest {
    private Context c;private String name;private android.content.SharedPreferences prefs;private Records.Factory records,oldRecords;private HomeSurfaces.Host oldHost;private HomeSurfaces.Reader oldReader;private final long now=java.time.Instant.parse("2026-10-25T08:00:00Z").toEpochMilli();
    @Before public void prepare()throws Exception{c=InstrumentationRegistry.getInstrumentation().getTargetContext();HomeSurfaces.drain(8000);name="home-widget-test-"+UUID.randomUUID();prefs=c.getSharedPreferences(name,0);records=context->new Store(context,name+".db");oldRecords=Records.factory;oldHost=HomeSurfaces.host;oldReader=HomeSurfaces.reader;Records.factory=records;HomeSurfaces.host=new HomeSurfaces.Host(){public int[] ids(Context context){return new int[0];}public void update(Context context,int id,RemoteViews views){throw new AssertionError("No real host");}};}
    @After public void cleanup()throws Exception{try{HomeSurfaces.drain(8000);}finally{Records.factory=oldRecords;HomeSurfaces.host=oldHost;HomeSurfaces.reader=oldReader;c.deleteDatabase(name+".db");c.deleteSharedPreferences(name);}}
    private HomeWidgetSummary read(boolean access){return HomeWidgetData.load(c,records,prefs,now,ZoneId.of("UTC"),access);}
    @Test public void freshDisabledAndAccessErrorStatesComeFromRealSavedData(){HomeWidgetSummary empty=read(true);assertEquals("No alarm enabled",empty.alarmTitle);assertEquals("No sleep records",empty.reportTitle);assertEquals(0,empty.record);try(Store store=records.open(c)){Alarm disabled=new Alarm(1);disabled.enabled=false;store.save(disabled);}assertEquals("No alarm enabled",read(true).alarmTitle);try(Store store=records.open(c)){Alarm enabled=new Alarm(2);enabled.enabled=true;store.save(enabled);}assertEquals("Alarm needs review",read(true).alarmTitle);assertEquals("Alarm access needed",read(false).alarmTitle);assertTrue(read(false).alarmNeedsAttention);}
    @Test public void nearestSavedDeadlineAndEditedRecordDurationReopenWithoutMutation()throws Exception{long record;try(Store store=records.open(c)){Alarm a=new Alarm(1);a.enabled=true;store.save(a);Alarm b=new Alarm(2);b.enabled=true;store.save(b);RecordDraft sleep=new RecordDraft(now-9*3600000L,now-3600000L);sleep.note="This note must never leave the app in a widget";sleep.awake.add(new RecordIntervals.Span(sleep.start+1000,sleep.start+601000));record=Records.create(store,sleep,ZoneId.of("UTC"),now);}assertTrue(prefs.edit().putLong("deadline_1",now+7200000).putLong("deadline_2",now+3600000).commit());Map<String,?> before=new HashMap<>(prefs.getAll());String database;try(Store store=records.open(c)){database=store.backup().toString();}HomeWidgetSummary summary=read(true);assertEquals("Next saved alarm",summary.alarmTitle);assertTrue(summary.alarmTime.contains("9")||summary.alarmTime.contains("09"));assertEquals("7 h 50 min",summary.reportDuration);assertEquals(record,summary.record);assertFalse((summary.reportTitle+summary.reportDuration+summary.reportDetail).contains("note"));assertEquals(before,prefs.getAll());try(Store store=records.open(c)){assertEquals(database,store.backup().toString());}}
    @Test public void badAlarmJsonCannotHideValidReportOrCrashTheHost()throws Exception{long record;try(Store store=records.open(c)){android.content.ContentValues corrupt=new android.content.ContentValues();corrupt.put("id",1);corrupt.put("data","invalid");store.getWritableDatabase().insertOrThrow("alarms",null,corrupt);record=Records.create(store,new RecordDraft(now-7200000,now-3600000),ZoneId.of("UTC"),now);}HomeWidgetSummary summary=read(true);assertEquals("Alarms unavailable",summary.alarmTitle);assertEquals(record,summary.record);assertEquals("1 h 0 min",summary.reportDuration);}
    @Test public void remoteViewsInflateNativeControlsAndExposeTruthfulAccessibleLabels()throws Exception{HomeWidgetSummary summary=read(true);AtomicReference<View> result=new AtomicReference<>();InstrumentationRegistry.getInstrumentation().runOnMainSync(()->result.set(HomeWidgetViews.render(c,summary).apply(c,new FrameLayout(c))));View root=result.get();assertEquals("Add an alarm",((TextView)root.findViewById(R.id.widget_alarm_value)).getText().toString());assertTrue(root.findViewById(R.id.widget_alarm).getContentDescription().toString().contains("No alarm enabled"));assertEquals("Open Add alarm editor",root.findViewById(R.id.widget_add).getContentDescription());assertEquals("Refresh SleepWell widget",root.findViewById(R.id.widget_refresh).getContentDescription());}
    @Test public void coalescedFakeHostRefreshRunsOffMainAndPreservesExactScopes()throws Exception{AtomicInteger loads=new AtomicInteger(),updates=new AtomicInteger();CountDownLatch published=new CountDownLatch(1);HomeSurfaces.reader=(context,pinned)->{assertNotEquals(Looper.getMainLooper(),Looper.myLooper());assertSame(records,pinned);loads.incrementAndGet();return read(true);};HomeSurfaces.host=new HomeSurfaces.Host(){public int[] ids(Context context){return new int[]{42};}public void update(Context context,int id,RemoteViews views){assertNotEquals(Looper.getMainLooper(),Looper.myLooper());assertEquals(42,id);updates.incrementAndGet();published.countDown();}};for(int n=0;n<50;n++)HomeSurfaces.changed(c);assertTrue(published.await(8,TimeUnit.SECONDS));HomeSurfaces.drain(8000);assertEquals(1,loads.get());assertEquals(1,updates.get());}
    @Test public void launchAndShortcutIntentsResolveOnlyToExpectedScreenRoutes()throws Exception{PackageManager manager=c.getPackageManager();for(HomeLaunch.Screen screen:HomeLaunch.Screen.values()){Intent intent=HomeLaunch.intent(c,screen,99);assertEquals(screen,HomeLaunch.read(intent));assertEquals(HomeLaunchActivity.class.getName(),intent.getComponent().getClassName());assertTrue(manager.getActivityInfo(intent.getComponent(),0).exported);if(screen!=HomeLaunch.Screen.ADD_ALARM){Intent target=HomeLaunch.target(c,screen,99);assertNotNull(manager.getActivityInfo(target.getComponent(),0));assertNull(target.getAction());assertFalse(target.hasExtra("recordSounds"));assertFalse(target.hasExtra("alarmRun"));}}assertNull(HomeLaunch.read(new Intent("untrusted").putExtra("screen","ADD_ALARM")));assertNull(HomeLaunch.read(new Intent(HomeLaunch.ACTION).putExtra("screen","RING_ALARM")));assertEquals(HistoryActivity.class.getName(),HomeLaunch.target(c,HomeLaunch.Screen.REPORT,-1).getComponent().getClassName());for(HomeLaunch.Screen screen:HomeShortcuts.SCREENS){ShortcutInfo info=HomeShortcuts.info(c,screen);assertEquals(screen,HomeLaunch.read(info.getIntent()));assertTrue(info.getId().startsWith("sleepwell-"));}assertFalse(manager.getReceiverInfo(new ComponentName(c,HomeWidgetProvider.class),0).exported);}
    @Test public void addAlarmShortcutCreatesOnlyAnUnsavedDraft(){AlarmDefaultsSettings.Factory previous=AlarmDefaultsSettings.factory;try{AlarmDefaultsSettings.factory=context->AlarmDefaultsSettings.of(prefs);try(Store store=records.open(c)){store.save(new Alarm(8));String before=store.backup().toString();Alarm draft=HomeLaunch.draft(c,store);assertEquals(9,draft.id);assertEquals(before,store.backup().toString());assertEquals(1,store.alarms().size());}}finally{AlarmDefaultsSettings.factory=previous;}}
}
